<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {RouterLink} from 'vue-router'
import {getSources,updateSource} from '../services/admin.ts'
const sources=ref<Awaited<ReturnType<typeof getSources>>>([]),busy=ref(false),error=ref(''),notice=ref('')
async function load(){busy.value=true;error.value='';try{sources.value=await getSources()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function save(){busy.value=true;error.value='';notice.value='';try{for(const s of sources.value)await updateSource(s.name,{enabled:s.enabled,page_size:s.page_size,max_retries:s.max_retries});notice.value='配置已保存'}catch(e){error.value=String(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="standard-page source-settings"><div class="page-heading"><div><div class="eyebrow">DATA MANAGEMENT</div><h1>来源配置</h1><p>设置来源状态、分页数量和请求重试次数。</p></div><RouterLink class="button button-secondary" to="/admin/overview">← 返回数据概览</RouterLink></div><p v-if="busy" role="status">正在读取或保存来源配置…</p><p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><form class="panel" @submit.prevent="save"><fieldset :disabled="busy"><article v-for="s in sources" :key="s.name"><h2>{{s.name}}</h2><label><input v-model="s.enabled" type="checkbox" :aria-label="`${s.name} 启用`"/> 启用来源</label><label>分页数量<input v-model.number="s.page_size" class="form-input" type="number" min="1" :max="s.name==='openalex'?100:1000" required :aria-label="`${s.name} 分页数量`"/></label><label>最多尝试次数<input v-model.number="s.max_retries" class="form-input" type="number" min="1" max="8" required :aria-label="`${s.name} 最多尝试次数`"/></label></article></fieldset><p>停用来源后将暂停该来源的新导入，已排队的任务继续处理。分页数量与最多尝试次数用于后续采集请求。</p><div class="actions"><button class="button button-primary" :disabled="busy||!sources.length">保存配置</button><button class="button button-secondary" :disabled="busy" type="button" @click="load">重新读取</button></div></form></section></template>
<style scoped>.source-settings .panel{padding:24px}.source-settings fieldset{border:0;padding:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:18px}.source-settings article{border:1px solid #e1ebea;padding:18px;border-radius:9px}.source-settings h2{font-size:16px;margin-bottom:14px}.source-settings label{display:block;font-size:12px;color:#69858b;margin:12px 0}.source-settings .form-input{display:block;width:100%;margin-top:7px}.source-settings p{font-size:12px;line-height:1.8;margin:16px 0;color:#69858b}.actions{display:flex;gap:12px;flex-wrap:wrap}@media(max-width:600px){.source-settings .page-heading{flex-direction:column}.source-settings .panel{padding:16px}}</style>
